void Solver::rephase() {
    rephases = 0;
    threshold *= 0.85;
    rephase_limit += 4096 + (int)(rephase_limit * 0.05);
    // Diversify the saved phases based on rephase count modulo strategy
    int strategy = rand() % 100;
    if ((strategy -= 40) < 0) {
        // Use local best phase (most common - exploitation)
        for (int i = 1; i <= vars; i++) saved[i] = local_best[i];
    } else if ((strategy -= 20) < 0) {
        // Use inverted local best phase
        for (int i = 1; i <= vars; i++) saved[i] = -local_best[i];
    } else if ((strategy -= 20) < 0) {
        // Random phase (exploration)
        for (int i = 1; i <= vars; i++) saved[i] = rand() % 2 ? 1 : -1;
    } else if ((strategy -= 10) < 0) {
        // Alternate local best and inverted
        for (int i = 1; i <= vars; i++) saved[i] = (i % 2 == 0) ? local_best[i] : -local_best[i];
    } else {
        // Keep current saved phases (do nothing)
    }
}
